package models

const unknownEnumString = "unknown"

// VCSType identifies the version control system managing a repo.
type VCSType int

// VCSType values.
const (
	VCSTypeGit VCSType = iota
	VCSTypeJJ
)

func (v VCSType) String() string {
	switch v {
	case VCSTypeGit:
		return "git"
	case VCSTypeJJ:
		return "jj"
	default:
		return unknownEnumString
	}
}

// FilterMode identifies a repo list filter criterion.
type FilterMode int

// FilterMode values.
const (
	FilterModeAll FilterMode = iota
	FilterModeAhead
	FilterModeBehind
	FilterModeDirty
	FilterModeHasPR
	FilterModeHasStash
	FilterModeHasNotes
)

// filterModeCount is the number of FilterMode values, used to cycle modes.
const filterModeCount = 7

func (f FilterMode) String() string {
	switch f {
	case FilterModeAll:
		return "All"
	case FilterModeAhead:
		return "Ahead"
	case FilterModeBehind:
		return "Behind"
	case FilterModeDirty:
		return "Dirty"
	case FilterModeHasPR:
		return "Has PR"
	case FilterModeHasStash:
		return "Has Stash"
	case FilterModeHasNotes:
		return "Has Notes"
	default:
		return "Unknown"
	}
}

// ShortKey returns the single-character key binding label for the filter mode.
func (f FilterMode) ShortKey() string {
	switch f {
	case FilterModeAll:
		return "a"
	case FilterModeAhead:
		return ">"
	case FilterModeBehind:
		return "<"
	case FilterModeDirty:
		return "d"
	case FilterModeHasPR:
		return "p"
	case FilterModeHasStash:
		return "s"
	case FilterModeHasNotes:
		return "n"
	default:
		return "?"
	}
}

// Next returns the next FilterMode in cyclic order.
func (f FilterMode) Next() FilterMode {
	return FilterMode((int(f) + 1) % filterModeCount)
}

// AllFilterModes returns every FilterMode in display order.
func AllFilterModes() []FilterMode {
	return []FilterMode{
		FilterModeAll,
		FilterModeAhead,
		FilterModeBehind,
		FilterModeDirty,
		FilterModeHasPR,
		FilterModeHasStash,
		FilterModeHasNotes,
	}
}

// SelectableFilterModes returns the FilterModes a user can toggle, excluding FilterModeAll.
func SelectableFilterModes() []FilterMode {
	return []FilterMode{
		FilterModeDirty,
		FilterModeAhead,
		FilterModeBehind,
		FilterModeHasPR,
		FilterModeHasStash,
		FilterModeHasNotes,
	}
}

